/**
 * Unit tests for goal-store load-time metadata migration.
 *
 * Pins the contract in `src/server/agent/goal-store.ts::load`:
 *  - absent metadata stays absent (no backfill);
 *  - a valid plain-object metadata survives a load round-trip;
 *  - malformed metadata (non-object / array / null) is dropped;
 *  - legacy per-goal `worktreeSetupCommand` / `worktreeSetupTimeoutMs` are
 *    dropped on load (superseded by metadata + goalProvisioned hook).
 */
import { describe, it } from "vitest";
import assert from "node:assert/strict";
import path from "node:path";

import { GoalStore, type PersistedGoal } from "../../../../src/server/agent/goal-store.ts";
import { TaskStore, type PersistedTask } from "../../../../src/server/agent/task-store.ts";
import { createMemFs, type MemFs } from "../../../../tests/support/harnesses/shared/mem-fs.js";

// Seed goals.json through the injected memfs, then load a GoalStore over the
// SAME memfs so the load-time migration runs entirely in memory.
function seed(goals: Array<Record<string, unknown>>): { store: GoalStore } {
	const memfs: MemFs = createMemFs();
	const dir = path.resolve("/memfs/goal-meta");
	memfs.mkdirSync(dir);
	memfs.writeFileSync(path.join(dir, "goals.json"), JSON.stringify(goals, null, 2), "utf-8");
	return { store: new GoalStore(dir, memfs) };
}

describe("goal-store metadata migration", () => {
	it("keeps a valid plain-object metadata", () => {
		const { store } = seed([{ id: "g1", title: "t", metadata: { "bobbit.disabledTools": ["x"] } }]);
		assert.deepEqual((store.get("g1") as PersistedGoal).metadata, { "bobbit.disabledTools": ["x"] });
	});

	it("leaves absent metadata absent (no backfill)", () => {
		const { store } = seed([{ id: "g1", title: "t" }]);
		assert.equal((store.get("g1") as PersistedGoal).metadata, undefined);
	});

	it("drops malformed metadata (array, scalar, null)", () => {
		const { store } = seed([
			{ id: "arr", title: "t", metadata: ["nope"] },
			{ id: "scalar", title: "t", metadata: "nope" },
			{ id: "null", title: "t", metadata: null },
		]);
		assert.equal((store.get("arr") as PersistedGoal).metadata, undefined);
		assert.equal((store.get("scalar") as PersistedGoal).metadata, undefined);
		assert.equal((store.get("null") as PersistedGoal).metadata, undefined);
	});

	it("drops legacy per-goal worktree setup fields on load", () => {
		const { store } = seed([{
			id: "g1",
			title: "t",
			worktreeSetupCommand: "echo hi",
			worktreeSetupTimeoutMs: 5000,
		}]);
		const g = store.get("g1") as PersistedGoal & {
			worktreeSetupCommand?: unknown;
			worktreeSetupTimeoutMs?: unknown;
		};
		assert.equal(g.worktreeSetupCommand, undefined);
		assert.equal(g.worktreeSetupTimeoutMs, undefined);
	});

	it("persists root scheduler recovery targets across a restart", async () => {
		const memfs = createMemFs();
		const dir = path.resolve("/memfs/scheduler-root-recovery-targets");
		const store = new GoalStore(dir, memfs);
		store.put({
			id: "root", title: "root",
			schedulerRecovery: { kind: "root", affectedChildGoalIds: ["child-a", "child-b"], code: "SCHEDULER_CIRCUIT_OPEN", reason: "storm", retryable: true, updatedAt: 1 },
		} as PersistedGoal);
		await store.flush();
		assert.deepEqual(new GoalStore(dir, memfs).get("root")!.schedulerRecovery?.affectedChildGoalIds, ["child-a", "child-b"]);
	});

	it("explicitly deletes scheduler recovery instead of silently stripping undefined", async () => {
		const memfs = createMemFs();
		const dir = path.resolve("/memfs/scheduler-recovery-delete");
		const store = new GoalStore(dir, memfs);
		store.put({
			id: "g1", title: "one", schedulerRecovery: { kind: "child", code: "RETRY_EXHAUSTED", reason: "busy", retryable: true, updatedAt: 1 },
		} as PersistedGoal);
		assert.equal(store.update("g1", { schedulerRecovery: undefined }), true, "generic update remains a no-op for undefined");
		assert.ok(store.get("g1")!.schedulerRecovery, "undefined did not delete the persisted field");
		assert.equal(store.clearSchedulerRecovery("g1"), true);
		assert.equal(store.get("g1")!.schedulerRecovery, undefined);
		await store.flush();
		assert.equal(new GoalStore(dir, memfs).get("g1")!.schedulerRecovery, undefined, "explicit delete persists across restart");
	});

	it("coalesces goal and task writes asynchronously and makes both snapshots durable on flush", async () => {
		const memfs = createMemFs();
		const dir = path.resolve("/memfs/coalesced-goal-task");
		let writes = 0;
		const writeAsync = memfs.promises.writeFile.bind(memfs.promises);
		(memfs.promises as any).writeFile = async (file: any, data: any, options?: any) => {
			writes++;
			return (writeAsync as any)(file, data, options);
		};
		const goals = new GoalStore(dir, memfs);
		const tasks = new TaskStore(dir, memfs);
		goals.put({ id: "g1", title: "one" } as PersistedGoal);
		goals.put({ id: "g2", title: "two" } as PersistedGoal);
		tasks.put({ id: "t1", goalId: "g1", title: "first", type: "testing", state: "todo", createdAt: 1, updatedAt: 1 } as PersistedTask);
		tasks.put({ id: "t2", goalId: "g1", title: "second", type: "testing", state: "todo", createdAt: 1, updatedAt: 1 } as PersistedTask);
		assert.equal(writes, 0, "hot mutation calls only schedule persistence");

		await Promise.all([goals.flush(), tasks.flush()]);
		assert.equal(writes, 2, "one atomic snapshot per independently coalesced store");
		assert.ok(goals.getPersistenceMetrics()?.bytes);
		assert.ok(tasks.getPersistenceMetrics()?.bytes);
		assert.equal(new GoalStore(dir, memfs).getAll().length, 2);
		assert.equal(new TaskStore(dir, memfs).getAll().length, 2);
		assert.equal(memfs.existsSync(path.join(dir, "goals.json.tmp")), false);
		assert.equal(memfs.existsSync(path.join(dir, "tasks.json.tmp")), false);
	});
});
